import{_ as r,o as s,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Optimism Erasure Coding- The Testing That Makes Us Confident","description":"","frontmatter":{"title":"Optimism Erasure Coding- The Testing That Makes Us Confident","date":"2025-06-24T00:00:00.000Z","updated":"2025-06-24T00:00:00.000Z","tags":["Ceph","Erasure Coding","Storage Testing","Data Consistency","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Optimism_Erasure_Coding_-_The_Testing_That_Makes_Us_Confident.md","filePath":"posts/2025/Optimism_Erasure_Coding_-_The_Testing_That_Makes_Us_Confident.md","lastUpdated":1780459816000}'),e={name:"posts/2025/Optimism_Erasure_Coding_-_The_Testing_That_Makes_Us_Confident.md"};function n(a,t,l,g,d,_){return s(),o("div",null,[...t[0]||(t[0]=[i('<h3 id="ceph-erasure-coding-测试工具开发会议纪要" tabindex="-1">Ceph Erasure Coding 测试工具开发会议纪要 <a class="header-anchor" href="#ceph-erasure-coding-测试工具开发会议纪要" aria-label="Permalink to &quot;Ceph Erasure Coding 测试工具开发会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><p>本次会议主要讨论了针对纠删码（Erasure Coding, EC）优化开发的测试工具“ceph IO sequence exerciser”的设计、功能模块以及测试场景。</p><h4 id="关键讨论内容" tabindex="-1">关键讨论内容 <a class="header-anchor" href="#关键讨论内容" aria-label="Permalink to &quot;关键讨论内容&quot;">​</a></h4><ol><li><p><strong>测试背景与目标</strong></p><ul><li><strong>Erasure Coding 特性测试</strong>：验证分片大小、k值边界条件、跨分片/跨条带的读写操作、多重叠写入等特定场景。</li><li><strong>工具设计目标</strong>： <ul><li>覆盖多样化测试场景，避免重复性测试。</li><li>支持错误注入，如模拟分片丢失、写入失败，以验证数据恢复和一致性。</li><li>提供可复现的测试序列，便于调试。</li></ul></li></ul></li><li><p><strong>工具核心功能</strong></p><ul><li><strong>数据生成</strong>：按块生成数据，支持自定义或预定义块大小，包含头部信息。</li><li><strong>错误注入</strong>：模拟分片丢失、写入失败等。</li><li><strong>IO 序列控制</strong>：支持自定义操作顺序，测试并发和边界条件。</li></ul></li><li><p><strong>典型测试用例</strong></p><ul><li><strong>跨分片写入</strong>：验证非完整分片写入、跨条带边界的读写。</li><li><strong>错误恢复测试</strong>：注入写入错误后检查数据回滚和重建。</li><li><strong>追加写入</strong>：测试对象尾部间隙的写入与读取一致性。</li></ul></li><li><p><strong>附加功能</strong></p><ul><li><strong>多线程/并行控制</strong>：支持多对象并发操作。</li><li><strong>交互模式</strong>：允许手动指定操作序列，便于调试。</li><li><strong>日志输出</strong>：实时打印操作详情，辅助开发和分析。</li></ul></li><li><p><strong>未来计划</strong></p><ul><li>集成到 Teuthology 测试框架中。</li><li>开放源码，欢迎社区贡献。</li></ul></li></ol><h4 id="决议与行动计划" tabindex="-1">决议与行动计划 <a class="header-anchor" href="#决议与行动计划" aria-label="Permalink to &quot;决议与行动计划&quot;">​</a></h4><ul><li><strong>短期行动</strong>：完成工具与 Teuthology 的集成测试，整理代码文档并发布到 GitHub。</li><li><strong>长期优化</strong>：扩展更多错误注入场景，增加对大规模集群的性能压测支持。</li></ul><h4 id="关键词保留" tabindex="-1">关键词保留 <a class="header-anchor" href="#关键词保留" aria-label="Permalink to &quot;关键词保留&quot;">​</a></h4><ul><li><strong>Erasure Coding (EC)</strong>、<strong>shard</strong>、<strong>stripe</strong>、<strong>CRUSH algorithm</strong>、<strong>OSD</strong>、<strong>Teuthology</strong></li><li><strong>consistency</strong>、<strong>recovery</strong>、<strong>RADOS</strong>、<strong>librados</strong>、<strong>replication</strong></li></ul><h4 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h4><p>工具源码和联系方式已共享，开发者可通过邮件或 GitHub 进一步参与。会议强调了自动化测试和边界条件覆盖对 Ceph 稳定性的重要性。</p>',11)])])}const p=r(e,[["render",n]]);export{u as __pageData,p as default};
